mapper.select:
SELECT
FROM t_leave l JOIN t_student s ON s.id = l.student_id JOIN t_class cl ON cl.id = s.class_id JOIN t_college cg ON cg.id = cl.college_id
l.student_id = #{studentId}
AND l.status = #{status}
ORDER BY l.id DESC

SELECT
FROM t_leave l JOIN t_student s ON s.id = l.student_id JOIN t_class cl ON cl.id = s.class_id JOIN t_college cg ON cg.id = cl.college_id
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR s.student_no LIKE CONCAT('%', #{keyword}, '%') OR l.leave_no LIKE CONCAT('%', #{keyword}, '%'))
AND l.status = #{status}
AND cg.id = #{collegeId}
AND l.leave_type = #{leaveType}
ORDER BY l.id DESC

SELECT
FROM t_leave l JOIN t_student s ON s.id = l.student_id JOIN t_class cl ON cl.id = s.class_id JOIN t_college cg ON cg.id = cl.college_id
EXISTS (SELECT 1 FROM t_leave_audit la WHERE la.leave_id = l.id AND la.operator_user_id = #{userId} AND la.action IN ('APPROVE', 'REJECT'))
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR l.leave_no LIKE CONCAT('%', #{keyword}, '%'))
l.status = 'PENDING_HEAD' AND cl.head_teacher_id = #{teacherId}
l.status = 'PENDING_COUNSELOR' AND cl.counselor_teacher_id = #{teacherId}
l.status = 'PENDING_LEADER' AND cg.leader_teacher_id = #{teacherId}
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR l.leave_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY l.id DESC

SELECT l.status AS name, COUNT(*) AS value FROM t_leave l
l.student_id = #{studentId}
GROUP BY l.status

SELECT l.leave_type AS name, COUNT(*) AS value FROM t_leave l
l.student_id = #{studentId}
GROUP BY l.leave_type
